(function () {
  'use strict';
  const D=KezhiDomain,S=KezhiService;
  let state=S.load()||D.fresh();
  state.taskFilter=state.taskFilter||'全部';state.taskOverrides=state.taskOverrides||{};state.chatMessages=state.chatMessages||[];state.assistantOpen=!!state.assistantOpen;
  let memoryFilter='全部', answer='', busy=false, modalFocus=null, dirty=false, mobileOpen=false;
  const app=document.getElementById('app'),overlay=document.getElementById('overlay');
  const pages={dashboard:'工作台',clients:'客户中心',clientDetail:'客户详情',tasks:'调整任务',memories:'客户记忆',reviews:'复盘与学习',logs:'操作记录'};
  const stepNames=['异常详情','诊断与依据','调整方案','确认执行','执行结果'];
  const c=()=>D.clients.find(x=>x.id===state.client)||D.clients[0];
  const r=()=>state.records[c().id];
  const t=()=>r().task;
  const baseBudgets=()=>t().currentBudgets||c().budgets;
  const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const money=x=>Number(x).toLocaleString('zh-CN');
  const fmt=x=>Number(x).toFixed(2);
  const date=x=>new Date(x).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
  const btn=(label,action,style='',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
  const badge=(label,tone='')=>`<span class="tag ${tone}">${esc(label)}</span>`;
  const init=(client)=>`<span class="initial ${client.color}">${client.initials}</span>`;
  function workTasks(){const titles=['ROI 连续低于目标','低效计划预算复核','新素材测试待确认','转化回传异常核查','大促预算边界确认','素材频次上升诊断','再营销计划复盘','库存变化影响核查','人群拓展方案审核','账户配置变更核对','周度经营复盘','素材偏好待确认','客户交接信息补全','阶段目标重新对齐','下周期测试计划'];return D.clients.map((client,i)=>({id:`T-${String(i+1).padStart(3,'0')}`,clientId:client.id,title:i===0?'ROI 连续低于目标':titles[i],priority:state.taskOverrides[`T-${String(i+1).padStart(3,'0')}`]||['紧急','重要','常规'][i%3],status:i%4===0?'处理中':'待处理',due:`09.${String(9+(i%6)).padStart(2,'0')}`,owner:client.owner,summary:`${client.name} · ${i%2?'核对经营上下文和数据证据后给出处理建议':'当前指标或客户信息发生变化，需要完成核查与确认'}`,source:['投放平台日报','客户微信沟通','周度复盘会议','广告账户配置'][i%4]}));}
  function assistantHTML(){const messages=state.chatMessages.length?state.chatMessages:[{role:'assistant',text:`你好，我是智慧客知。可以帮你查找 ${c().name} 的经营信息、任务、记忆和复盘。`}];return `<button class="assistant-fab" data-action="assistant-toggle" aria-label="打开智慧客知"><img src="assets/zhihui-kezhi.png" alt=""><span>智慧客知</span></button>${state.assistantOpen?`<aside class="assistant-panel" aria-label="智慧客知对话"><header><div><strong>智慧客知</strong><small>${c().name} · 信息查询</small></div><button class="close" data-action="assistant-toggle" aria-label="关闭">×</button></header><div class="assistant-messages">${messages.map(m=>`<div class="chat ${m.role}"><p>${esc(m.text)}</p>${(m.cards||[]).map(card=>`<button class="answer-card" data-smart-link="${card.page}" data-client="${card.clientId||state.client}"><strong>${esc(card.title)}</strong><span>${esc(card.detail)}</span><small>${esc(card.meta)} →</small></button>`).join('')}</div>`).join('')}</div><div class="assistant-suggestions">${['有哪些紧急任务？','查看客户素材偏好','最近的复盘结论','准备交接摘要'].map(q=>`<button data-smart-question="${q}">${q}</button>`).join('')}</div><div class="assistant-input"><input id="assistant-input" placeholder="输入想查询的内容" aria-label="咨询智慧客知"><button class="btn primary compact" data-action="assistant-send">发送</button></div></aside>`:''}`;}
  function save(){if(!S.save(state))toast('当前浏览器无法保存本地进度，请勿关闭页面。');}
  function log(title,detail='',clientId=state.client){state.records[clientId].logs.unshift({id:Date.now()+Math.random(),time:new Date().toISOString(),title,detail,version:state.records[clientId].task.version});save();}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200);}
  for(const record of Object.values(state.records)){
    record.task.diagnosisLoading=false;
    if(record.task.execution?.status==='running')record.task.execution=D.settleExecution(record.task.execution,'unknown');
  }
  function taskStatus(task){if(task.execution)return {success:'调整完成 · 待观察',partial:'执行待核对',unknown:'执行待核对',failed:'执行失败',running:'执行中'}[task.execution.status];if(task.selection==='observe'&&task.stage===3)return '待补充信息';return task.stage>=3?'待确认执行':task.stage>=2?'待选择方案':task.diagnosed?'待选择方案':task.stage===1?'待诊断':'待诊断';}
  function render(){
    const active=state.page==='task'?'tasks':state.page==='clientDetail'?'clients':state.page;
    app.innerHTML=`<div class="layout"><aside class="sidebar ${mobileOpen?'open':''}" aria-label="主导航">
      <div class="brand"><div class="brandmark">知</div><div><div class="brandname">客知</div><sub>KEZHI GROWTH</sub></div></div>
      <div class="nav-caption">客户增长工作空间</div>
      <nav>${[['dashboard','工作台','01'],['clients','客户中心','02'],['tasks','调整任务','03'],['memories','客户记忆','04'],['reviews','复盘与学习','05'],['logs','操作记录','06']].map(([id,name,n])=>`<button class="nav-item ${active===id?'active':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}><span class="nav-marker">${n}</span>${name}${id==='tasks'?'<span class="nav-count">1</span>':''}</button>`).join('')}</nav>
      <div class="sidebar-note">记住每个客户的不同<br>让每次增长建议有据可循</div>
      <div class="sidebar-bottom"><button class="demo-control" data-action="settings">运行设置 <span style="float:right">···</span></button><div class="profile"><span class="avatar">陈</span><div><strong>陈宁</strong><small>优化师 · 增长服务组</small></div></div></div>
    </aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu" data-action="mobile" aria-label="切换导航">☰</button><span class="muted">增长工作空间</span><span class="muted">/</span><strong>${state.page==='task'?'调整任务':pages[state.page]||'工作台'}</strong></div><div class="top-actions"><span class="muted">数据日期 2026.09.09</span><span class="tag outline"><span class="dot"></span> 数据已同步</span><select class="client-select" id="client-select" aria-label="当前客户">${D.clients.map(x=>`<option value="${x.id}" ${state.client===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div></header>
    <div class="content">${view()}<div class="footer-note"><span>客知增长 Agent · 记忆有来源，调整有记录</span><span>客户数据更新于 09.09 09:00</span></div></div></main>${assistantHTML()}</div>`;
    bindCharts();
  }
  function head(title,subtitle,actions='',eyebrow='CLIENT GROWTH WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="btn-row">${actions}</div></div>`;}
  function feature(title,desc){return `<div class="feature-line"><strong>${title}</strong><span>${desc}</span></div>`;}
  function view(){switch(state.page){case'dashboard':return dashboard();case'clients':return clientsView();case'clientDetail':return clientDetailView();case'tasks':return tasksView();case'task':return taskView();case'memories':return memoriesView();case'reviews':return reviewsView();case'logs':return logsView();default:return dashboard();}}
  function spark(client){const pts=client.series.map((v,i)=>`${i*15+1},${25-(v-1)*8}`).join(' ');return `<svg class="spark" viewBox="0 0 80 28" aria-label="近六天趋势"><polyline points="${pts}" fill="none" stroke="${client.id==='qinghe'?'#b78b5b':'#769168'}" stroke-width="1.6"/></svg>`;}
  function chart(client,wide=false){const vals=client.series;const xs=[52,157,262,367,472,577],y=v=>190-v*42;const pts=vals.map((v,i)=>`${xs[i]},${y(v)}`);const targetY=y(client.target);return `<div class="chart" data-chart="${client.id}"><svg viewBox="0 0 630 223" role="img" aria-label="${client.name}近六天投放ROI趋势，目标${client.target}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#bfd0b0" stop-opacity=".32"/><stop offset="100%" stop-color="#dce7d3" stop-opacity=".04"/></linearGradient></defs>${[1,2,3,4].map(v=>`<line class="chart-grid" x1="42" y1="${y(v)}" x2="600" y2="${y(v)}"/><text class="chart-label" x="10" y="${y(v)+4}">${v.toFixed(1)}</text>`).join('')}<path d="M${pts.join(' L')} L577,190 L52,190 Z" fill="url(#chartFill)"/><line class="chart-target" x1="42" y1="${targetY}" x2="600" y2="${targetY}"/><text class="chart-label" x="594" y="${targetY-8}" text-anchor="end" style="fill:#b08a58">目标 ${fmt(client.target)}</text><polyline class="chart-line" points="${pts.join(' ')}"/>${vals.map((v,i)=>`<circle class="chart-point" tabindex="0" role="img" aria-label="9月${i+3}日，ROI ${fmt(v)}" data-point="${i}" cx="${xs[i]}" cy="${y(v)}" r="3.4"><title>09.${i+3} · ROI ${fmt(v)}</title></circle><text class="chart-label" x="${xs[i]}" y="215" text-anchor="middle">09.0${i+3}</text>`).join('')}</svg><div class="chart-tooltip" hidden></div></div><div class="chart-legend"><span><i class="legend-line"></i>投放 ROI</span><span><i class="legend-line target"></i>目标 ROI</span><span style="margin-left:auto">09.03 — 09.08 · 每日数据</span></div>`;}
  function bindCharts(){document.querySelectorAll('[data-chart]').forEach(el=>{const client=D.clients.find(x=>x.id===el.dataset.chart);el.querySelectorAll('[data-point]').forEach(dot=>{const show=()=>{const i=+dot.dataset.point;const tooltip=el.querySelector('.chart-tooltip');tooltip.hidden=false;tooltip.innerHTML=`09.0${i+3} · ${client.name}<br>ROI ${fmt(client.series[i])}<br>消耗 ¥${money(client.cap)} · 成交 ¥${money(client.cap*client.series[i])}`;};dot.addEventListener('mouseenter',show);dot.addEventListener('focus',show);dot.addEventListener('mouseleave',()=>el.querySelector('.chart-tooltip').hidden=true);dot.addEventListener('blur',()=>el.querySelector('.chart-tooltip').hidden=true);});});}
  function dashboard(){
    const client=c(),q=state.records.qinghe.task,done=q.execution?.status==='success';
    return head('每个客户，都心中有数。','从值得关注的变化开始，把时间留给真正重要的增长判断。',btn('操作指南','guide')+btn('处理 ROI 异常 <span class="arrow">↗</span>','start-qinghe','primary'))+
      `<div class="metrics">${metric('服务中的客户',String(D.clients.length).padStart(2,'0'),'位',`${D.clients.length} 个广告账户 · ${new Set(D.clients.map(x=>x.business)).size} 类经营行业`)}${metric('待处理异常',String(D.clients.filter(x=>x.roi<x.target).length).padStart(2,'0'),'项',done?'青禾调整完成，其他异常待处理':'青禾家居 ROI 低于目标',!done)}${metric('待确认记忆',Object.values(state.records).reduce((s,v)=>s+v.memories.filter(m=>m.status==='待确认').length,0).toString().padStart(2,'0'),'条','确认后才能用于客户长期经验')}${metric('历史复盘',Object.values(state.records).reduce((s,v)=>s+v.reviews.length,0).toString(),'项','结果、限制和经验均已归档')}</div>
      <div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>投放表现 <span class="count-label">${client.name}</span></h2><p>把变化放回时间里，先看趋势，再做判断。</p></div><span class="date-pill">近 6 天</span></div><div class="card-body"><div class="detail-metrics"><div class="detail-metric"><label>最近 3 天 ROI</label><strong>${fmt(client.roi)}</strong><small class="${client.roi<client.target?'highlight':''}">${client.roi<client.previous?'较上期下降':'较上期上升'} ${fmt(Math.abs(client.roi/client.previous-1)*100)}%</small></div><div class="detail-metric"><label>广告消耗</label><strong><span style="font-size:17px">¥</span> ${money(client.spend)}</strong><small>最近 3 天累计</small></div><div class="detail-metric"><label>归因成交金额</label><strong><span style="font-size:17px">¥</span> ${money(client.revenue)}</strong><small>同口径归因数据</small></div></div>${chart(client)}<div class="chart-summary"><span>数据截至 09.08 23:59 · 回传完整</span><button class="source-link" data-action="roi-definition">查看指标口径</button></div></div></section>
      <div class="stack"><section class="card"><div class="card-head"><div><h2>优先关注 <span class="count-label">${done?'0':'1'}</span></h2><p>关键变化，带着上下文一起看。</p></div>${badge(done?'待观察':'需要处理',done?'success':'warning')}</div><div class="card-body"><div class="alert-item"><div class="alert-meta">${init(D.clients[0])}<span>青禾家居 · 旗舰店</span></div><div class="alert-heading" style="margin-top:14px"><h3>${done?'预算调整已完成':'ROI 连续低于目标'}</h3></div><p>${done?'A、B 计划预算已完成调整。回报是否改善，需等待完整观察周期。':'最近 3 天 ROI <strong>2.00</strong>，低于目标 <strong>2.50</strong>。旧素材计划占 60% 消耗，建议优先核查。'}</p>${btn(done?'查看执行结果 →':'查看异常与依据 →','start-qinghe','primary compact')}</div></div></section><section class="card"><div class="card-head"><div><h2>接下来做什么</h2><p>把确认、行动和复盘连起来。</p></div></div><div class="card-body"><div class="task-mini"><div><h3>核实客户素材偏好</h3><p>${client.name} · ${r().memories.filter(m=>m.status==='待确认').length} 条待确认信息</p></div>${btn('查看','nav-memories','ghost compact')}</div><div class="task-mini"><div><h3>${done?'到期检查调整效果':'保留本次调整的观察安排'}</h3><p>${done?'已有复盘待办 · 等待观察数据':'完成调整后自动建立复盘待办'}</p></div>${btn('查看','nav-reviews','ghost compact')}</div></div></section></div></div>
      <section class="card section-gap"><div class="card-head"><div><h2>我的客户 <span class="count-label">${D.clients.length}</span></h2><p>目标、状态与下一步，一眼掌握。</p></div>${btn('客户中心 →','nav-clients','ghost compact')}</div><div class="toolbar"><div class="tabs">${['all','risk','stable'].map((v,i)=>`<button class="tab ${state.filter===v?'active':''}" data-filter="${v}">${['全部客户','需关注','表现稳定'][i]}</button>`).join('')}</div><input class="search" id="client-search" placeholder="搜索客户名称" aria-label="搜索客户名称" value="${esc(state.search)}"></div><div id="client-table">${clientTable()}</div></section>`;
  }
  function metric(label,value,unit,foot,warning=false){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot"><span class="${warning?'warn':''}">${warning?'● ':''}${foot}</span></div></div>`;}
  function clientTable(){const group=state.clientGroup||'全部行业',term=state.search.toLowerCase();const list=D.clients.filter(x=>(state.filter==='all'||(state.filter==='risk'?x.roi<x.target:x.roi>=x.target))&&(group==='全部行业'||x.business===group)&&[x.name,x.business,x.product,x.style].join(' ').toLowerCase().includes(term));return list.length?`<div class="table-wrap"><table><thead><tr><th>客户 / 主营</th><th>业务分类</th><th>偏好类型</th><th>投放 ROI</th><th>目标 ROI</th><th>近 3 天消耗</th><th>当前状态</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td><div class="client-cell">${init(x)}<div><strong>${x.name}</strong><small>${x.product} · ${x.region}</small></div></div></td><td>${badge(x.business)}</td><td>${badge(x.style,'outline')}</td><td><span class="table-number ${x.roi<x.target?'warn':''}">${fmt(x.roi)}</span></td><td>${fmt(x.target)}</td><td class="mono">¥${money(x.spend)}</td><td>${badge(x.id==='qinghe'&&state.records[x.id].task.execution?.status==='success'?'调整后待观察':x.status,x.roi<x.target?'warning':'success')}</td><td><button class="btn ghost compact" data-client-detail="${x.id}">了解详情 →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>没有找到匹配客户</h3><p>试试其他名称，或清除筛选条件。</p>${btn('清除筛选','clear-filter')}</div>`;}
  function clientsView(){const businesses=[...new Set(D.clients.map(x=>x.business))],styles=[...new Set(D.clients.map(x=>x.style))];return head('客户中心','先按行业与偏好了解客户组合，再进入单个客户查看经营详情。',btn('客户记忆总览','nav-memories','primary'),'CLIENT PORTFOLIO')+feature('相似客户，集中管理','行业决定经营指标，偏好帮助理解素材和沟通方式；客户数据仍保持独立。')+`<div class="client-groups"><button class="group-card ${(state.clientGroup||'全部行业')==='全部行业'?'active':''}" data-client-group="全部行业"><strong>${D.clients.length}</strong><span>全部客户</span><small>完整客户组合</small></button>${businesses.map(g=>`<button class="group-card ${state.clientGroup===g?'active':''}" data-client-group="${g}"><strong>${D.clients.filter(x=>x.business===g).length}</strong><span>${g}</span><small>${[...new Set(D.clients.filter(x=>x.business===g).map(x=>x.product))].slice(0,2).join('、')}</small></button>`).join('')}</div><section class="card section-gap"><div class="card-head"><div><h2>客户分类与服务状态 <span class="count-label">${D.clients.length}</span></h2><p>支持按行业、偏好和异常状态快速筛选。</p></div><div class="preference-summary">${styles.map(s=>`<span class="tag outline">${s} · ${D.clients.filter(x=>x.style===s).length}</span>`).join('')}</div></div><div class="toolbar"><div class="tabs">${['all','risk','stable'].map((v,i)=>`<button class="tab ${state.filter===v?'active':''}" data-filter="${v}">${['全部状态','需关注','表现稳定'][i]}</button>`).join('')}</div><input class="search" id="client-search" placeholder="搜索客户、行业或商品" aria-label="搜索客户" value="${esc(state.search)}"></div><div id="client-table">${clientTable()}</div></section>`;}
  function clientDetailView(){const client=c(),mem=r().memories,confirmed=mem.filter(m=>m.status==='已确认').length;return head(client.name,'客户经营信息、沟通习惯与接班重点集中呈现。',btn('返回客户中心','nav-clients')+btn('查看全部记忆','nav-memories','primary'),'CLIENT PROFILE')+`<div class="intro-panel"><div class="client-banner">${init(client)}<div><h2>${client.name}</h2><p>${client.account} · ${client.category} · 服务自 ${client.serviceSince}</p></div></div><div class="profile-tags">${badge(client.business)}${badge(client.style,'outline')}${badge(client.region,'outline')}${badge(client.roi<client.target?'需关注':'表现稳定',client.roi<client.target?'warning':'success')}</div></div><div class="four-col"><section class="card"><div class="card-head"><div><h2>基础信息</h2><p>快速了解客户经营轮廓。</p></div></div><div class="card-body">${[['主营商品',client.product],['核心受众',client.audience],['成立时间',client.established],['重点区域',client.region],['投放账户',client.account],['负责优化师',client.owner]].map(([k,v])=>`<div class="context-row"><span>${k}</span><p>${v}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>经营与投放</h2><p>目标、预算和当前表现。</p></div></div><div class="card-body">${[['阶段目标','投放 ROI '+fmt(client.target)],['当前 ROI',fmt(client.roi)],['近 3 天消耗','¥'+money(client.spend)],['归因成交','¥'+money(client.revenue)],['日预算上限','¥'+money(client.cap)],['当前重点',client.note]].map(([k,v])=>`<div class="context-row"><span>${k}</span><p>${v}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>沟通与决策</h2><p>接班后知道怎样协作。</p></div></div><div class="card-body">${[['客户联系人',client.contact],['同步节奏',client.cadence],['决策习惯',client.decisionStyle],['素材偏好',client.preference],['有效记忆',confirmed+' 条'],['待确认信息',mem.filter(m=>m.status==='待确认').length+' 条']].map(([k,v])=>`<div class="context-row"><span>${k}</span><p>${v}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>交接摘要</h2><p>接班先看重点，再追溯来源。</p></div></div><div class="card-body"><div class="context-row"><span>当前状态</span><p>${client.id==='qinghe'?taskStatus(t()):client.status}</p></div><div class="context-row"><span>接班提醒</span><p>${client.handoff}</p></div><div class="context-row"><span>历史积累</span><p>${r().reviews.length} 条复盘 · ${r().logs.length} 条操作记录</p></div><div class="btn-row" style="margin-top:18px">${btn('生成交接摘要','handoff','ghost')}${client.id==='qinghe'?btn('进入调整任务','open-task','primary'):''}</div></div></section></div><section class="card section-gap"><div class="card-head"><div><h2>经营上下文摘录</h2><p>来源标签随记录展示，接班时无需逐条打开。</p></div>${btn('管理全部记忆','nav-memories','ghost compact')}</div><div class="card-body context-list">${mem.slice(0,12).map(m=>`<div class="context-record"><div>${badge(m.type)}${badge(m.sourceTag||m.source.split(' · ')[0],'outline')}</div><p>${esc(m.text)}</p><small>${esc(m.source)} · ${m.status}</small></div>`).join('')}</div></section>`;}
  function tasksView(){const list=workTasks().filter(x=>state.taskFilter==='全部'||x.priority===state.taskFilter);const counts=p=>workTasks().filter(x=>x.priority===p).length;return head('调整任务','按轻重缓急安排工作，先处理对客户经营影响最大的事项。',btn('进入青禾 ROI 任务','start-qinghe','primary'),'ADJUSTMENT TASKS')+feature('三级优先级，主动安排处理顺序','紧急任务优先控制风险，重要任务影响阶段目标，常规任务按计划持续推进。')+`<div class="priority-board">${[['紧急','今天优先处理','关键指标异常或执行风险'],['重要','本周期完成','影响目标、素材或客户决策'],['常规','按计划推进','例行复盘、补全和跟进']].map(([p,label,desc])=>`<button class="priority-card ${state.taskFilter===p?'active':''}" data-task-filter="${p}"><strong>${counts(p)}</strong><div><span>${p} · ${label}</span><small>${desc}</small></div></button>`).join('')}</div><section class="card section-gap"><div class="card-head"><div><h2>全部任务 <span class="count-label">${list.length}</span></h2><p>选择任务查看详情，也可以重新设置优先级。</p></div><div class="tabs">${['全部','紧急','重要','常规'].map(p=>`<button class="tab ${state.taskFilter===p?'active':''}" data-task-filter="${p}">${p}</button>`).join('')}</div></div><div class="table-wrap"><table class="task-table"><thead><tr><th>优先级</th><th>任务 / 客户</th><th>状态</th><th>截止</th><th>负责人</th><th>信息来源</th><th></th></tr></thead><tbody>${list.map(task=>{const client=D.clients.find(x=>x.id===task.clientId);return `<tr><td><select class="priority-select" data-task-priority="${task.id}" aria-label="${task.title}优先级">${['紧急','重要','常规'].map(p=>`<option ${p===task.priority?'selected':''}>${p}</option>`).join('')}</select></td><td><div class="client-cell">${init(client)}<div><strong>${task.title}</strong><small>${task.summary}</small></div></div></td><td>${badge(task.status,task.status==='处理中'?'warning':'')}</td><td>${task.due}</td><td>${task.owner}</td><td>${badge(task.source,'outline')}</td><td><button class="btn ghost compact" data-task-detail="${task.id}">查看详情 →</button></td></tr>`}).join('')}</tbody></table></div></section>`;}
  function steps(){return `<nav class="steps" aria-label="调整任务步骤">${stepNames.map((s,i)=>`<button class="step ${t().stage===i?'current':t().stage>i?'done':''}" data-step="${i}" ${i>t().maxStage||t().execution&&i<4?'disabled':''} ${t().stage===i?'aria-current="step"':''}><span class="step-num">${t().stage>i?'✓':i+1}</span><span>${s}</span></button>`).join('')}</nav>`;}
  function taskView(){if(c().id!=='qinghe')return tasksView();return head('改善投放 ROI','青禾家居旗舰店 · 总预算不变，在客户约束内做出具体调整。',btn('任务列表','nav-tasks')+badge('进行中','outline'),'ADJUSTMENT / QH-0909')+steps()+[anomalyView,diagnosisView,strategyView,confirmView,resultView][t().stage]();}
  function plansTable(edit=false){return `<div class="table-wrap"><table><thead><tr><th>投放计划</th><th>消耗</th><th>归因成交</th><th>ROI</th><th>日预算</th><th></th></tr></thead><tbody>${c().plans.map((p,i)=>`<tr><td><strong style="font-weight:500">${String.fromCharCode(65+i)} · ${p}</strong></td><td>¥${money(c().rows[i][0])}</td><td>¥${money(c().rows[i][1])}</td><td class="table-number ${i===0?'warn':''}">${fmt(c().rows[i][1]/c().rows[i][0])}</td><td>¥${money(baseBudgets()[i])}</td><td>${btn('详情','plan-'+i,'ghost compact')}</td></tr>`).join('')}</tbody></table></div>`;}
  function anomalyView(){return feature('先看清变化，再开始调整','指标、时间窗口和客户限制放在一起，减少来回查找。')+(!t().infoComplete?`<div class="validation warning">转化数据尚未回传完整。可以查看当前数据，暂不生成执行方案。${btn('补齐数据','complete-data','ghost compact')}</div>`:'')+`<div class="two-col"><section class="card"><div class="card-head"><div><h2>ROI 低于目标 20%</h2><p>最近 3 天：09.06 — 09.08，对比 09.03 — 09.05。</p></div>${badge('需要关注','warning')}</div><div class="card-body"><div class="detail-metrics"><div class="detail-metric"><label>最近 3 天</label><strong>2.00</strong><small class="highlight">较上期下降 33.3%</small></div><div class="detail-metric"><label>前一个 3 天</label><strong>3.00</strong><small>同等消耗 ¥3,000</small></div><div class="detail-metric"><label>客户目标</label><strong>2.50</strong><small>低于目标 20%</small></div></div>${chart(c())}<p class="definition">ROI = 广告归因成交金额 ÷ 广告消耗，非利润回报。<button class="source-link" data-action="roi-definition">口径说明</button></p></div></section><section class="card"><div class="card-head"><div><h2>这位客户的边界</h2><p>已确认要求，始终参与后续校验。</p></div>${btn('全部','nav-memories','ghost compact')}</div><div class="card-body">${r().memories.filter(m=>['budget','total','style','approve'].includes(m.id)).map(m=>`<div class="context-row"><div class="memory-tags">${badge(m.type)}${badge(m.sourceTag||m.source.split(' · ')[0],'outline')}</div><p>${esc(m.text)}</p><small class="source-inline">来源：${esc(m.source)} · ${m.status}</small><button class="source-link" style="margin-top:9px" data-memory="${m.id}">查看详情</button></div>`).join('')}</div></section></div><section class="card section-gap"><div class="card-head"><div><h2>计划表现拆解</h2><p>先定位消耗与回报，再判断是否需要更多证据。</p></div><span class="tag">09.06 — 09.08</span></div>${plansTable()}</section><div class="action-bar"><p>数据更新于 09.09 09:00<br>${t().infoComplete?'回传完整，可以进入诊断。':'转化回传待补齐，诊断将提示信息缺口。'}</p>${btn('分析原因 →','diagnose','primary')}</div>`;}
  function diagnosisView(){if(busy&&!t().diagnosed)return `<section class="card"><div class="loading"><div class="spinner"></div><h2>正在整理数据与客户背景</h2><p>核查时间窗口 · 关联客户约束 · 整理证据<br>正在形成诊断结论</p></div></section>`;return feature('每条判断，都能展开依据','区分已知事实与原因假设，证据不足时先补查。')+`<div class="two-col"><div class="stack"><section class="card"><div class="card-head"><div><h2>建议优先核查 A 计划</h2><p>当前观察支持有限测试，尚不支持确定性归因。</p></div>${badge('诊断完成','success')}</div><div class="card-body"><article class="insight"><div class="insight-label">01 / 已观察事实</div><p>A 计划消耗 <strong>¥1,800，占比 60%</strong>，ROI 为 <strong>1.50</strong>，低于客户目标。B 计划 ROI 为 <strong>3.00</strong>，但消耗规模较小。</p><button class="source-link" data-evidence="metrics">[E01] 查看计划数据</button></article><article class="insight"><div class="insight-label">02 / 原因假设 ${badge('待验证','warning')}</div><p>计划预算分布可能影响整体回报。素材、受众与转化回传的变化仍需进一步检查，不能直接认定旧素材失效。</p><button class="source-link" data-evidence="limits">[E02] 查看判断限制</button></article><article class="insight"><div class="insight-label">03 / 可行动方向</div><p>在日总预算不变的条件下，将 A 的少量预算转入 B，观察扩大投放后的表现。保留明确的人工复核条件。</p><button class="source-link" data-memory="budget">[M01] 查看预算授权依据</button></article></div></section><section class="card"><div class="card-head"><div><h2>补充业务背景</h2><p>把线下变化带进本次判断，不直接写入长期记忆。</p></div></div><div class="card-body"><div class="field"><textarea id="supplement" placeholder="例如：本周没有促销，主推商品库存正常。" aria-label="补充业务背景">${esc(t().supplement)}</textarea></div><div class="questions">${['为什么不能直接增加预算？','为什么考虑 B 计划？','旧素材已经失效了吗？'].map((q,i)=>`<button class="question" data-question="${i}">${q}</button>`).join('')}</div>${answer?`<div class="answer">${answer}</div>`:''}<div class="btn-row"><input class="text-input" style="flex:1;min-width:120px" id="free-question" placeholder="输入其他问题" aria-label="其他问题">${btn('提问','free-question')}</div><div class="btn-row" style="margin-top:13px">${btn('保存补充信息','save-supplement','ghost compact')}</div></div></section></div><div class="stack"><section class="card"><div class="card-head"><div><h2>证据清单</h2><p>只引用当前客户的数据与记录。</p></div></div><div class="card-body"><div class="evidence-row"><span class="evidence-num">E01</span><div><p>近 3 天计划表现</p><small>09.06 — 09.08 · 广告账户数据</small><button class="source-link" data-evidence="metrics">展开数据</button></div></div><div class="evidence-row"><span class="evidence-num">M01</span><div><p>日预算上限 ¥1,000</p><small>预算确认单 · 已确认</small><button class="source-link" data-memory="budget">查看原文</button></div></div><div class="evidence-row"><span class="evidence-num">M02</span><div><p>优先使用真人实拍素材</p><small>素材偏好 · 不等同于效果结论</small><button class="source-link" data-memory="style">查看原文</button></div></div></div></section><section class="card"><div class="card-head"><div><h2>仍需留意</h2><p>把不确定性保留在决策中。</p></div></div><div class="card-body"><p class="inline-note">缺少不同计划的受众、素材频次与同期变化数据，当前不能判断 ROI 下降的唯一原因。增量预算的实际回报需通过后续观察验证。</p>${!t().infoComplete?`<div class="validation warning">转化数据尚未完整。${btn('补齐数据','complete-data','ghost compact')}</div>`:''}</div></section></div></div><div class="action-bar">${btn('返回异常详情','back')}<div class="btn-row"><span class="inline-note">方案将遵守当前已确认的客户限制</span>${btn(busy?'正在生成…':'生成调整方案 →','generate','primary',busy||!t().infoComplete?'disabled':'')}</div></div>`;}
  function strategyView(){const task=t();return feature('把建议变成可核对的动作','预算前后值、判断依据和观察安排，一起交给你确认。')+`<div class="plan-choices"><button class="select-card ${task.selection==='adjust'?'selected':''}" data-select-plan="adjust"><span class="selection-dot"></span>${badge('建议方案','success')}<h3>小幅调整，验证预算表现</h3><p>从 A 计划转移 ¥100 至 B 计划，日总预算保持不变。<br>调整有限，实际收益仍需观察。</p></button><button class="select-card ${task.selection==='observe'?'selected':''}" data-select-plan="observe"><span class="selection-dot"></span>${badge('备选方案')}<h3>保持配置，补充验证</h3><p>暂不改预算，补查素材频次、受众与转化数据。<br>信息更充分，改善动作相应延后。</p></button></div>${task.selection==='observe'?`<section class="card"><div class="card-head"><div><h2>补查清单</h2><p>不产生投放写入动作。</p></div></div><div class="card-body"><ol class="guide-list"><li>核查 A、B 计划受众与投放时间差异。</li><li>补充素材频次、点击率及转化率数据。</li><li>确认活动、库存和归因回传是否发生变化。</li></ol><p class="inline-note">负责人：陈宁 · 下一工作日跟进</p></div></section><div class="action-bar">${btn('返回诊断','back')}${btn('建立补查待办','create-investigation','primary')}</div>`:`<div class="two-col"><div class="stack"><section class="card"><div class="card-head"><div><h2>预算调整明细 <span class="count-label" id="version-label">V${task.version}</span></h2><p>支持直接编辑，所有调整实时检查预算边界。</p></div>${btn('恢复推荐值','restore-budgets','ghost compact')}</div><div class="table-wrap"><table><thead><tr><th>投放计划</th><th>当前日预算</th><th>调整后 / 元</th><th>变化</th></tr></thead><tbody>${c().plans.map((p,i)=>`<tr><td>${String.fromCharCode(65+i)} · ${p}</td><td>¥${money(baseBudgets()[i])}</td><td><input class="budget-input" aria-label="${String.fromCharCode(65+i)}计划调整后预算" id="budget-${i}" data-budget="${i}" type="number" min="0" step="1" value="${esc(task.budgets[i])}"></td><td id="delta-${i}" class="change">${delta(task.budgets[i]-baseBudgets()[i])}</td></tr>`).join('')}</tbody></table></div><div class="budget-total"><span>调整后日总预算 <small> / 上限 ¥1,000</small></span><strong id="budget-sum">¥${money(task.budgets.reduce((s,v)=>s+Number(v||0),0))}</strong></div></section><section class="card"><div class="card-head"><div><h2>观察与复核</h2><p>在动作发生前，先约定何时看结果。</p></div></div><div class="card-body"><div class="field-row"><div class="field"><label for="days">观察周期 / 完整自然日</label><input id="days" type="number" min="1" max="30" value="${task.days}"><small>周期结束且转化数据完整后复盘</small></div><div class="field"><label for="threshold">日 ROI 低于此值时人工复核</label><input id="threshold" type="number" min="0.01" step="0.1" value="${task.threshold}"><small>当前配置，不触发自动回滚</small></div></div><div class="field"><label for="plan-note">调整备注</label><textarea id="plan-note" placeholder="补充本次调整的考虑…">${esc(task.note)}</textarea></div></div></section></div><div class="stack"><section class="card"><div class="card-head"><div><h2>为什么适合这个客户</h2><p>方案调用的客户信息可以逐条核对。</p></div></div><div class="card-body"><div class="context-row"><span>符合经营边界</span><p>日总预算不增加，保留小规模验证。</p><button class="source-link" data-memory="total" style="margin-top:9px">查看客户要求</button></div><div class="context-row"><span>依据当前观察</span><p>B 计划 ROI 3.00，值得有限测试，不能直接推算扩大后的收益。</p><button class="source-link" data-evidence="metrics" style="margin-top:9px">查看数据依据</button></div>${r().memories.filter(m=>m.id.startsWith('experience')&&m.status==='已确认').map(m=>`<div class="context-row"><span>已确认的历史经验</span><p>${esc(m.text)}</p><button class="source-link" data-memory="${m.id}">查看来源</button></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>需要接受的风险</h2><p>动作可控，效果仍有不确定性。</p></div></div><div class="card-body"><p class="inline-note">B 计划扩大预算后可能出现边际回报下降。计划间存在受众差异，本次调整不等同于随机对照实验，也不承诺 ROI 提升。</p></div></section></div></div><div id="validation-area">${validationHtml()}</div><div class="action-bar"><div class="btn-row">${btn('返回诊断','back')}${btn('保存草稿','save-draft','ghost')}</div><div class="btn-row"><span class="inline-note" id="draft-hint">${dirty?'有未保存修改':'草稿已保存至本地'}</span>${btn('预览执行 →','preview','primary',D.validate(c(),task,r().memories).length?'disabled':'')}</div></div>`}`;}
  function delta(v){return v===0?'不变':`${v>0?'+':'−'} ¥${money(Math.abs(v))}`;}
  function validationHtml(){const errors=D.validate(c(),t(),r().memories);return errors.length?`<div class="validation error" role="alert">${errors.map(e=>`<div>${e}</div>`).join('')}</div>`:`<div class="validation">已通过检查：总预算保持不变 · 客户约束有效 · 参数符合要求</div>`;}
  function updateValidation(){const area=document.getElementById('validation-area');if(area)area.innerHTML=validationHtml();const sum=document.getElementById('budget-sum');if(sum)sum.textContent='¥'+money(t().budgets.reduce((s,v)=>s+Number(v||0),0));t().budgets.forEach((v,i)=>{const el=document.getElementById('delta-'+i);if(el)el.textContent=delta(Number(v)-baseBudgets()[i]);const input=document.getElementById('budget-'+i);if(input)input.setAttribute('aria-invalid',v===''||!Number.isInteger(Number(v))||Number(v)<0?'true':'false');});const preview=document.querySelector('[data-action="preview"]');if(preview)preview.disabled=!!D.validate(c(),t(),r().memories).length;const ver=document.getElementById('version-label');if(ver)ver.textContent='V'+t().version;const hint=document.getElementById('draft-hint');if(hint)hint.textContent='有未保存修改';}
  function budgetSummary(execution=null){const rows=execution?execution.items:c().plans.map((name,i)=>({name,from:baseBudgets()[i],to:Number(t().budgets[i])}));return `<div class="table-wrap"><table><thead><tr><th>投放计划</th><th>调整前</th><th>目标日预算</th><th>${execution?'执行状态':'变化'}</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${String.fromCharCode(65+i)} · ${x.name}</td><td>¥${money(x.from)}</td><td><strong>¥${money(x.to)}</strong></td><td>${execution?executionBadge(x.status):delta(x.to-x.from)}</td></tr>`).join('')}</tbody></table></div>`;}
  function confirmView(){if(t().selection==='observe')return `<section class="card"><div class="empty"><div class="empty-number">01</div><h3>补查待办已建立</h3><p>负责人：陈宁 · 下一工作日跟进<br>补查素材频次、受众差异及回传状态，当前没有投放写入动作。</p><div class="btn-row" style="justify-content:center">${btn('返回方案比较','back')}${btn('查看操作记录','nav-logs','primary')}</div></div></section>`;const errors=D.validate(c(),t(),r().memories);return feature('确认的是具体动作，不是一句建议','请核对账户、方案版本与参数；返回修改后需重新确认。')+`<div class="two-col"><section class="card"><div class="card-head"><div><h2>执行预览 <span class="count-label">V${t().version}</span></h2><p>执行前请再次核对投放账户与预算参数。</p></div>${badge('等待确认','warning')}</div><div class="card-body"><dl class="summary-grid"><div><dt>客户</dt><dd>${c().name}</dd></div><div><dt>投放账户</dt><dd>${c().account}</dd></div><div><dt>批准版本</dt><dd>方案 V${t().version}</dd></div><div><dt>日总预算</dt><dd>¥1,000 → ¥1,000</dd></div></dl></div>${budgetSummary()}<div class="card-body" style="padding-top:20px"><label class="check-row"><input type="checkbox" id="acknowledge" ${t().acknowledged?'checked':''} ${errors.length?'disabled':''}><span>我已核对客户、账户和上述调整内容，确认按方案 V${t().version} 进行本次投放执行。</span></label></div></section><div class="stack"><section class="card"><div class="card-head"><div><h2>执行前检查</h2><p>把执行条件核实清楚，再提交动作。</p></div></div><div class="card-body">${errors.length?`<div class="validation error">${errors.join('<br>')}</div>`:['账户与当前客户一致','总预算未增加','关键客户约束已确认','方案参数有效'].map(x=>`<div class="context-row"><p><span class="tag success" style="display:inline;margin-right:9px">通过</span>${x}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>执行后观察</h2><p>完成配置，不代表效果已经改善。</p></div></div><div class="card-body"><p class="inline-note">观察 ${t().days} 个完整自然日；日 ROI 低于 ${fmt(t().threshold)} 时提醒人工复核。数据回传完整后再评价结果。</p></div></section></div></div><div class="action-bar">${btn('返回修改','back')}<div class="btn-row"><span class="inline-note">确认仅绑定当前方案版本</span>${btn('确认并执行','execute','primary',!t().acknowledged||errors.length||busy?'disabled':'')}</div></div>`;}
  function executionBadge(status){const names={pending:'等待提交',success:'已成功',failed:'执行失败',unknown:'状态待确认',unchanged:'保持不变'};return badge(names[status]||status,status==='success'?'success':status==='failed'?'danger':status==='unknown'?'warning':'');}
  function resultView(){const ex=t().execution;if(!ex)return `<section class="card"><div class="empty"><h3>还没有执行记录</h3>${btn('返回调整方案','back')}</div></section>`;const running=ex.status==='running';const success=ex.status==='success';const meta={running:['正在执行投放调整','正在核查配置并按顺序调整预算，请稍候。',''],success:['投放调整已完成','所有目标动作均已核对成功。效果待观察，ROI 异常尚未认定恢复。',''],partial:['部分调整完成，需要核对','先查询当前配置，再对未完成项重新预检。已成功项不会重复提交。','warning'],failed:['本次执行未完成','投放接口拒绝了本次调整，预算未修改。可以重新预检后再确认。','danger'],unknown:['执行状态暂未确认','提交结果暂时未知，请先查询状态，勿重复提交。','warning']}[ex.status];return `<div class="execution-banner ${meta[2]}"><div class="execution-mark">${success?'✓':running?'…':'!'}</div><div><h2>${meta[0]}</h2><p>${meta[1]}</p></div></div>${running?`<section class="card"><div class="loading"><div class="spinner"></div><h2>正在核查执行结果</h2><p>先减少 A 预算，再增加 B 预算，避免中间状态超出总预算。</p></div></section>`:`<div class="two-col"><section class="card"><div class="card-head"><div><h2>逐项执行结果</h2><p>${esc(ex.id)} · 方案 V${ex.version} · ${date(ex.finished||ex.started)}</p></div>${badge('执行批次','outline')}</div>${budgetSummary(ex)}<div class="card-body" style="padding-top:20px"><p class="inline-note">${success?'当前日预算合计 ¥1,000，已核对与批准方案一致。':ex.status==='partial'?'当前已确认：A ¥500、B ¥300、C ¥100，合计 ¥900。B 的目标调整尚未完成。':ex.status==='unknown'?'预算实际状态尚未确认，查询完成前不展示确定配置。':'当前日预算仍为执行前配置。'}</p></div></section><section class="card"><div class="card-head"><div><h2>${success?'下一步：观察实际效果':'下一步：核对并恢复'}</h2><p>${success?'调整结束后，工作继续有序跟进。':'状态明确以后，再决定是否补交。'}</p></div></div><div class="card-body"><div class="context-row"><span>${success?'复盘安排':'处理说明'}</span><p>${success?`${t().days} 个完整自然日后，待回传完整再复盘。`:ex.status==='unknown'?'查询会返回本次执行的最终执行结果。':ex.status==='partial'?'重新核对当前配置，只重试尚未成功的目标动作。':'重新检查方案与客户约束，确认后重试。'}</p></div><div class="context-row"><span>责任人</span><p>陈宁 · 优化师</p></div>${success?btn('查看复盘待办 →','nav-reviews','primary'):btn(busy?'正在查询…':ex.status==='unknown'?'查询执行状态':'核对配置并准备重试','query-execution','primary',busy?'disabled':'')}</div></section></div>`}<div class="action-bar">${btn('返回工作台','nav-dashboard')}<div class="btn-row">${btn('查看操作记录','nav-logs','ghost')}${success?btn('查看观察安排','nav-reviews','primary'):''}</div></div>`;}
  function memoriesView(){const categories=['全部',...[...new Set(r().memories.map(m=>m.type))],'待确认'],list=r().memories.filter(m=>memoryFilter==='全部'||memoryFilter==='待确认'?memoryFilter==='全部'||m.status==='待确认':m.type===memoryFilter),sources=[...new Set(r().memories.map(m=>m.sourceTag||m.source.split(' · ')[0]))];return head('客户记忆','客户说过的要求、验证过的经验，下一次决策都能用上。',btn('新增记忆','add-memory','primary'),'CUSTOMER MEMORY')+feature('来源跟着记录走','事实、偏好和假设分开保存；每条记录直接显示来源、有效期和确认状态。')+`<div class="memory-stats"><div><strong>${r().memories.length}</strong><span>全部记录</span></div><div><strong>${r().memories.filter(m=>m.status==='已确认').length}</strong><span>已确认</span></div><div><strong>${r().memories.filter(m=>m.status==='待确认').length}</strong><span>待核实</span></div><div><strong>${sources.length}</strong><span>信息来源</span></div></div><div class="memory-filter"><div class="tabs">${categories.map(x=>`<button class="tab ${memoryFilter===x?'active':''}" data-memory-filter="${x}">${x}</button>`).join('')}</div><span class="inline-note">${c().name} · 当前显示 ${list.length} 条</span></div><div class="memory-grid">${list.map(m=>`<article class="memory-card"><div class="memory-tags">${badge(m.type,m.type==='硬约束'||m.type==='预算约束'?'warning':'')}${badge(m.sourceTag||m.source.split(' · ')[0],'outline')}</div><h3>${esc(m.text)}</h3><div class="record-source"><strong>来源</strong><span>${esc(m.source)}</span></div><p>有效至 ${m.expires} · V${m.version}</p><div class="memory-actions">${badge(m.status,m.status==='已确认'?'success':m.status==='待确认'?'warning':'')}<div><button class="source-link" data-memory="${m.id}">详情</button><button class="btn ghost compact" data-edit-memory="${m.id}">${m.status==='待确认'?'核实':'编辑'}</button></div></div></article>`).join('')}</div>`;}
  function reviewsView(){const review=t().review,history=r().reviews;const active=review?`<section class="card"><div class="card-head"><div><h2>当前预算调整复盘</h2><p>${c().name} · 方案 V${t().execution.version} · ${esc(t().execution.id)}</p></div>${badge(review.confirmed?'已沉淀经验':review.loaded?'观察数据已就绪':'等待观察期',review.confirmed?'success':'warning')}</div><div class="card-body">${!review.loaded?`<div class="summary-grid"><div><dt>观察安排</dt><dd>${t().days} 个完整自然日，待转化回传完整</dd></div><div><dt>人工复核条件</dt><dd>日 ROI 低于 ${fmt(t().threshold)}</dd></div></div>${btn('载入观察期数据','load-review','primary')}`:`<div class="review-values"><div class="review-value"><small>调整前 ROI</small><strong>2.00</strong><p>成交 ¥6,000 / 消耗 ¥3,000</p></div><div class="review-value"><small>观察期 ROI</small><strong>2.40</strong><p>成交 ¥7,200 / 消耗 ¥3,000</p></div><div class="review-value"><small>客户目标</small><strong>2.50</strong><p>结果仍低于目标 4%</p></div></div><div class="insight"><div class="insight-label">结果与限制</div><p>ROI 从 2.00 变为 2.40，尚未达到 2.50。缺少随机对照，只记录观察变化，不将全部变化归因于预算调整。</p></div><h3 style="margin:20px 0 12px">客户经验草稿</h3><div class="field"><textarea id="review-draft" ${review.confirmed?'readonly':''}>${esc(review.draft)}</textarea></div><div class="btn-row" style="margin-top:18px">${review.confirmed?btn('查看已确认记忆','nav-memories','primary'):btn('确认经验并写入记忆','confirm-review','primary')}</div>`}</div></section>`:'';return head('复盘与学习','把实际结果整理成经验，让下一次判断有所依据。',btn('查看调整任务','nav-tasks'),'REVIEW & LEARNING')+feature('结果、限制、经验一起归档','每次复盘都保留来源与适用条件，避免把一次变化当成长期规律。')+`<div class="memory-stats"><div><strong>${history.length+(review?1:0)}</strong><span>复盘总数</span></div><div><strong>${history.filter(x=>x.result==='达到预期').length}</strong><span>达到预期</span></div><div><strong>${history.filter(x=>x.result==='继续观察').length}</strong><span>继续观察</span></div><div><strong>${r().memories.filter(x=>x.type==='历史经验').length}</strong><span>已沉淀经验</span></div></div>${active}<section class="card section-gap"><div class="card-head"><div><h2>历史复盘 <span class="count-label">${history.length}</span></h2><p>按时间查看历次策略、结果与证据来源。</p></div></div><div class="table-wrap"><table><thead><tr><th>日期</th><th>复盘主题</th><th>ROI 变化</th><th>结果</th><th>结论摘要</th><th>来源</th></tr></thead><tbody>${history.map(x=>`<tr><td class="nowrap">${x.date}</td><td><strong>${x.title}</strong></td><td class="mono">${fmt(x.before)} → ${fmt(x.after)}</td><td>${badge(x.result,x.result==='达到预期'?'success':x.result==='未达到'?'danger':'warning')}</td><td>${x.summary}</td><td>${badge(x.source.split(' · ')[0],'outline')}<small class="source-inline">${x.source}</small></td></tr>`).join('')}</tbody></table></div></section>`;}
  function logsView(){return head('操作记录','谁确认了什么，哪些动作已执行，都有记录可查。',btn('导出当前客户记录','export-logs'),'ACTIVITY LOG')+feature('动作、版本、来源完整留痕','从数据同步到客户交接，按时间追踪当前客户的每次关键操作。')+`<div class="memory-stats"><div><strong>${r().logs.length}</strong><span>全部记录</span></div><div><strong>${new Set(r().logs.map(x=>x.source||'系统操作')).size}</strong><span>记录来源</span></div><div><strong>${Math.max(...r().logs.map(x=>x.version))}</strong><span>最新版本</span></div><div><strong>${r().logs.filter(x=>x.title.includes('确认')).length}</strong><span>确认动作</span></div></div><section class="card"><div class="card-head"><div><h2>${c().name}的操作记录 <span class="count-label">${r().logs.length}</span></h2><p>来源、操作者与对象同步记录，便于复核和交接。</p></div>${btn('返回调整任务','nav-tasks','ghost compact')}</div><div class="card-body">${r().logs.map(l=>`<div class="log-row"><div class="log-time">${date(l.time).replace(' ','<br>')}</div><div style="flex:1"><div class="log-title"><h3>${esc(l.title)}</h3>${badge(l.source||'客户工作台','outline')}</div><p>${esc(l.detail)}</p></div><span class="tag">V${l.version}</span></div>`).join('')}</div></section>`;}
  function taskDetail(id){const task=workTasks().find(x=>x.id===id),client=D.clients.find(x=>x.id===task.clientId),record=state.records[client.id];openModal(`${task.id} · ${task.title}`,`<div class="task-detail-head">${init(client)}<div><h2>${client.name}</h2><p>${client.account} · ${client.business}</p></div>${badge(task.priority,task.priority==='紧急'?'danger':task.priority==='重要'?'warning':'')}</div><div class="summary-grid"><div><dt>任务状态</dt><dd>${task.status}</dd></div><div><dt>截止时间</dt><dd>${task.due}</dd></div><div><dt>负责人</dt><dd>${task.owner}</dd></div><div><dt>信息来源</dt><dd>${task.source}</dd></div></div><div class="source-block">${task.summary}</div><h3>处理要求</h3><ol class="guide-list"><li>核对客户目标、预算约束和最新账户数据。</li><li>区分已观察事实、原因假设和仍缺少的信息。</li><li>形成可执行建议，记录风险、观察周期和停止条件。</li></ol><div class="task-related"><div><strong>${record.memories.length}</strong><span>客户记忆</span></div><div><strong>${record.reviews.length}</strong><span>历史复盘</span></div><div><strong>${record.logs.length}</strong><span>操作记录</span></div></div>`,btn('关闭','close-modal')+(client.id==='qinghe'?btn('进入完整任务','open-task-modal','primary'):btn('查看客户详情','client-detail-modal','primary')),true);overlay.querySelector('.drawer').dataset.clientId=client.id;}
  function smartAnswer(query){const q=query.trim();if(!q)return;const client=c(),tasks=workTasks(),cards=[];let text='我找到了这些相关信息，你可以直接打开对应内容。';if(/紧急|任务|优先/.test(q)){tasks.filter(x=>x.priority==='紧急').slice(0,3).forEach(x=>cards.push({page:'tasks',clientId:x.clientId,title:x.title,detail:D.clients.find(c=>c.id===x.clientId).name,meta:`${x.priority} · 截止 ${x.due}`}));}else if(/偏好|素材|记忆/.test(q)){r().memories.filter(x=>/偏好|素材/.test(x.type+x.text)).slice(0,3).forEach(x=>cards.push({page:'memories',title:x.text,detail:x.source,meta:x.type}));}else if(/复盘|历史|结论/.test(q)){r().reviews.slice(0,3).forEach(x=>cards.push({page:'reviews',title:x.title,detail:x.summary,meta:`${x.date} · ${x.result}`}));}else if(/交接|接班|客户/.test(q)){cards.push({page:'clientDetail',title:`${client.name}客户详情`,detail:client.handoff,meta:'基础信息 · 沟通决策 · 交接摘要'});}else{cards.push({page:'clientDetail',title:`了解${client.name}`,detail:client.note,meta:'客户详情'});cards.push({page:'tasks',title:'查看待处理任务',detail:`当前共有 ${tasks.length} 项任务`,meta:'按优先级查看'});}state.chatMessages.push({role:'user',text:q},{role:'assistant',text,cards});save();render();setTimeout(()=>document.querySelector('.assistant-messages')?.scrollTo(0,99999),30);}
  function openModal(title,body,footer='',drawer=false){modalFocus=document.activeElement;overlay.innerHTML=`<div class="overlay-backdrop"><section class="${drawer?'drawer':'modal'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close-modal" aria-label="关闭对话框">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>overlay.querySelector('input,textarea,select,button')?.focus(),30);}
  function closeModal(){overlay.innerHTML='';document.body.style.overflow='';modalFocus?.focus();}
  function memoryDrawer(id){const m=r().memories.find(x=>x.id===id);if(!m)return;openModal('客户记忆 · 来源详情',`${badge(m.type)} ${badge(m.status,m.status==='已确认'?'success':'warning')}<h2 style="line-height:1.9;margin-top:20px">${esc(m.text)}</h2><div class="source-block">${esc(m.original)}</div><div class="source-meta"><span>所属客户</span><strong>${c().name}</strong><span>信息来源</span><strong>${esc(m.source)}</strong><span>有效期</span><strong>至 ${m.expires}</strong><span>确认状态</span><strong>${m.status} · V${m.version}</strong><span>调用规则</span><strong>${m.type==='硬约束'?'相关任务与执行预检始终校验':'仅在当前客户相关任务中参考'}</strong></div><div class="validation">客户偏好不等于效果事实；待验证假设不自动成为长期结论。</div>`,btn('关闭','close-modal'),true);}
  function evidenceDrawer(id){if(id==='metrics')openModal('证据 E01 · 计划表现',`<p>青禾家居旗舰店 · 09.06 — 09.08<br>来源：广告账户数据 · 更新时间 09.09 09:00</p><div style="margin:20px -20px">${plansTable()}</div><div class="source-block">A 占总消耗 60%，当前 ROI 1.50；B 当前 ROI 3.00。计划差异不构成因果证据，也不证明增加预算后回报保持不变。</div><p>周期 ROI 使用总归因成交金额 ÷ 总消耗计算。</p>`,btn('关闭','close-modal'),true);else openModal('证据 E02 · 判断限制',`<div class="source-block">当前未提供素材频次、分计划受众变化、完整漏斗与对照实验数据。</div><p>因此可以定位低回报计划，但不能确定素材疲劳、受众饱和或预算分配是唯一原因。建议有限调整并跟踪，不给出确定收益承诺。</p>`,btn('关闭','close-modal'),true);}
  function editMemory(id){const m=r().memories.find(x=>x.id===id);if(!m)return;const locked=['budget','total','approve'].includes(id);openModal('核实客户记忆',`<p style="margin-bottom:18px">${locked?'关键约束文本由客户授权记录维护，可复核状态和有效期。':'保存前请核对来源，明确区分偏好、事实与假设。'}</p><div class="field"><label for="memory-text">记忆内容</label><textarea id="memory-text" ${locked?'readonly':''}>${esc(m.text)}</textarea></div><div class="field"><label for="memory-status">状态</label><select id="memory-status">${['已确认','待确认','已停用','已过期'].map(v=>`<option ${m.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="memory-expiry">有效至</label><input id="memory-expiry" type="date" value="${m.expires}"></div><div class="validation warning">修改关键约束后，已有执行确认失效，需要重新检查方案。</div>`,btn('取消','close-modal')+`<button class="btn primary" data-save-memory="${id}">保存记忆</button>`);}
  function settings(){if(busy){toast('请等待当前操作结束后再切换场景。');return;}openModal('运行设置',`<p>切换可重复的运行分支。场景作用于当前客户的后续执行；已执行记录保持不变。</p><div class="field" style="margin-top:20px"><label for="scenario">执行场景</label><select id="scenario">${[['success','正常成功'],['failed','全部失败'],['partial','部分成功：A 成功，B 失败'],['unknown','状态未知：查询后确认成功'],['conflict','提交前配置已变化']].map(([v,label])=>`<option value="${v}" ${t().scenario===v?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="data-mode">数据状态</label><select id="data-mode"><option value="complete" ${t().infoComplete?'selected':''}>转化回传完整</option><option value="incomplete" ${!t().infoComplete?'selected':''}>转化回传不完整</option></select></div><div class="field"><label for="memory-mode">关键记忆状态</label><select id="memory-mode"><option value="valid" ${r().memories[0].status==='已确认'?'selected':''}>预算授权已确认</option><option value="expired" ${r().memories[0].status!=='已确认'?'selected':''}>预算授权已过期</option></select></div><div class="divider"></div><div class="btn-row">${btn('查看操作指南','guide','ghost')}${btn('重置全部业务数据','reset-confirm','danger')}</div>`,btn('取消','close-modal')+btn('保存设置','save-settings','primary'));}
  function guide(){openModal('5 分钟操作指南',`<p>建议从青禾家居开始。按以下步骤可完整了解异常处理流程。</p><ol class="guide-list"><li>工作台：点击“处理 ROI 异常”。</li><li>异常详情：查看趋势、计划表现与预算约束。</li><li>诊断：展开证据，体验三个预设追问。</li><li>方案：编辑预算，试试超限校验，再恢复推荐值。</li><li>确认：核对账户，勾选后执行。</li><li>结果：核对动作，进入复盘加载阶段观察数据。</li><li>学习：确认经验，回到客户记忆查看来源。</li></ol><div class="validation">异常分支在“运行设置”切换。刷新保留进度；“重置全部业务数据”可恢复初始状态。</div>`,btn('关闭','close-modal')+btn('开始操作','guide-start','primary'));}
  function go(page){if(busy){toast('当前操作进行中，请稍候。');return;}const proceed=()=>{state.page=page;answer='';mobileOpen=false;dirty=false;save();render();window.scrollTo(0,0);};if(dirty){openModal('离开当前编辑？','<p>当前方案有未保存修改。可以保存草稿后离开，或继续编辑。</p>',btn('继续编辑','close-modal')+btn('保存并离开','leave-save','primary'));pendingLeave=proceed;}else proceed();}
  let pendingLeave=null;
  function switchClient(id){if(busy){toast('当前操作进行中，请稍候再切换客户。');render();return;}const proceed=()=>{state.client=id;state.page=state.page==='task'?'tasks':state.page;state.filter='all';state.search='';answer='';memoryFilter='全部';dirty=false;save();render();};if(dirty){openModal('切换客户？','<p>当前方案有未保存修改，保存后再切换客户。</p>',btn('继续编辑','close-modal')+btn('保存并离开','leave-save','primary'));pendingLeave=proceed;}else proceed();}
  function gotoStep(i){if(busy||i>t().maxStage||t().execution&&i<4)return;if(i===3&&D.validate(c(),t(),r().memories).length){toast('请先修正方案校验问题。');return;}if(t().stage===2&&dirty){log('保存方案草稿',`预算 ${t().budgets.join(' / ')} 元`);dirty=false;}t().stage=i;t().acknowledged=false;save();render();window.scrollTo(0,0);}
  function changed(){if(!dirty)t().version++;dirty=true;t().acknowledged=false;updateValidation();}
  document.addEventListener('input',e=>{const el=e.target;if(el.id==='client-search'){state.search=el.value;document.getElementById('client-table').innerHTML=clientTable();save();}if(el.dataset.budget!==undefined){t().budgets[+el.dataset.budget]=el.value===''?'':Number(el.value);changed();}if(el.id==='days'||el.id==='threshold'){t()[el.id]=el.value===''?'':Number(el.value);changed();}if(el.id==='plan-note'){t().note=el.value;changed();}if(el.id==='supplement'){t().supplement=el.value;save();}if(el.id==='review-draft'){t().review.draft=el.value;save();}});
  document.addEventListener('change',e=>{const el=e.target;if(el.id==='client-select')switchClient(el.value);if(el.dataset.taskPriority){state.taskOverrides[el.dataset.taskPriority]=el.value;save();render();toast('任务优先级已更新。');}if(el.id==='acknowledge'){t().acknowledged=el.checked;const b=document.querySelector('[data-action="execute"]');b.disabled=!el.checked;}});
  document.addEventListener('click',async e=>{
    const target=e.target.closest('button');if(!target||target.disabled)return;
    if(target.dataset.nav){go(target.dataset.nav);return;}
    if(target.dataset.filter){state.filter=target.dataset.filter;save();render();return;}
    if(target.dataset.clientGroup){state.clientGroup=target.dataset.clientGroup;state.filter='all';state.search='';save();render();return;}
    if(target.dataset.clientDetail){state.client=target.dataset.clientDetail;state.page='clientDetail';state.search='';memoryFilter='全部';save();render();window.scrollTo(0,0);return;}
    if(target.dataset.taskFilter){state.taskFilter=target.dataset.taskFilter;save();render();return;}
    if(target.dataset.taskDetail){taskDetail(target.dataset.taskDetail);return;}
    if(target.dataset.smartQuestion){smartAnswer(target.dataset.smartQuestion);return;}
    if(target.dataset.smartLink){state.client=target.dataset.client||state.client;state.page=target.dataset.smartLink;state.assistantOpen=false;save();render();window.scrollTo(0,0);return;}
    if(target.dataset.openClient){state.filter='all';state.search='';switchClient(target.dataset.openClient);go('clients');return;}
    if(target.dataset.memory){memoryDrawer(target.dataset.memory);return;}
    if(target.dataset.evidence){evidenceDrawer(target.dataset.evidence);return;}
    if(target.dataset.editMemory){editMemory(target.dataset.editMemory);return;}
    if(target.dataset.memoryFilter){memoryFilter=target.dataset.memoryFilter;render();return;}
    if(target.dataset.step!==undefined){gotoStep(+target.dataset.step);return;}
    if(target.dataset.question!==undefined){answer=['当前客户明确要求日预算上限 ¥1,000，本次总预算不变。增加预算超出本次授权，应先与客户重新确认。','B 计划近 3 天 ROI 3.00，高于 A 的 1.50，因此值得小幅测试。但受众和规模不同，不保证扩大后回报保持不变。','还没有。现有数据只能说明 A 当前回报偏低，缺少频次、素材漏斗及对照数据，不能认定旧素材已经失效。'][+target.dataset.question];render();return;}
    if(target.dataset.selectPlan){if(t().selection!==target.dataset.selectPlan){t().selection=target.dataset.selectPlan;t().version++;t().acknowledged=false;save();}render();return;}
    if(target.dataset.saveMemory){const m=r().memories.find(x=>x.id===target.dataset.saveMemory),text=document.getElementById('memory-text').value.trim(),expiry=document.getElementById('memory-expiry').value,status=document.getElementById('memory-status').value;if(!text||!expiry){toast('请填写记忆内容和有效期。');return;}if(status==='已确认'&&expiry<'2026-09-09'){toast('有效期早于当前日期，请更新有效期或标记已过期。');return;}m.text=text;m.status=status;m.expires=expiry;m.version++;t().acknowledged=false;if(!t().execution)t().maxStage=Math.min(t().maxStage,2);log('更新客户记忆',`${m.type}：${m.text}；状态 ${m.status}`);closeModal();render();toast('客户记忆已更新，相关方案需重新校验。');return;}
    const action=target.dataset.action;if(!action)return;
    if(action.startsWith('nav-')){go(action.slice(4));return;}
    if(action.startsWith('plan-')){const i=+action.slice(5);openModal(`${String.fromCharCode(65+i)} · ${c().plans[i]}`,`<p>${c().name} · ${c().account}</p><div class="source-block">最近 3 天消耗 ¥${money(c().rows[i][0])}<br>广告归因成交金额 ¥${money(c().rows[i][1])}<br>投放 ROI ${fmt(c().rows[i][1]/c().rows[i][0])}<br>当前日预算 ¥${money(baseBudgets()[i])}</div><p>计划数据 · 09.06 — 09.08<br>当前表现不能直接预测预算变化后的回报。</p>`,btn('关闭','close-modal'),true);return;}
    switch(action){
      case'mobile':mobileOpen=!mobileOpen;render();break;
      case'assistant-toggle':state.assistantOpen=!state.assistantOpen;save();render();break;
      case'assistant-send':{const input=document.getElementById('assistant-input');smartAnswer(input?.value||'');break;}
      case'open-task-modal':{const id=overlay.querySelector('.drawer')?.dataset.clientId;closeModal();state.client=id||'qinghe';go('task');break;}
      case'client-detail-modal':{const id=overlay.querySelector('.drawer')?.dataset.clientId;closeModal();state.client=id||state.client;go('clientDetail');break;}
      case'close-modal':closeModal();break;
      case'leave-save':log('保存方案草稿',`预算 ${t().budgets.join(' / ')} 元`);dirty=false;closeModal();pendingLeave?.();pendingLeave=null;break;
      case'settings':settings();break;
      case'guide':guide();break;
      case'guide-start':closeModal();startQinghe();break;
      case'start-qinghe':startQinghe();break;
      case'open-task':go('task');break;
      case'clear-filter':state.search='';state.filter='all';save();render();break;
      case'roi-definition':openModal('投放 ROI · 指标口径',`<div class="source-block">投放 ROI = 广告归因成交金额 ÷ 广告消耗</div><p>当前口径使用广告平台归因成交金额，不扣除商品成本、退款和履约费用，因此不代表利润 ROI。</p><div class="divider"></div><p>最近 3 天：¥6,000 ÷ ¥3,000 = 2.00<br>前一个 3 天：¥9,000 ÷ ¥3,000 = 3.00<br>环比下降：(3.00 − 2.00) ÷ 3.00 = 33.3%<br>低于目标：(2.50 − 2.00) ÷ 2.50 = 20%</p>`,btn('知道了','close-modal'));break;
      case'diagnose':if(busy)break;busy=true;t().stage=1;t().maxStage=Math.max(1,t().maxStage);t().diagnosed=false;save();render();try{await S.diagnose(state.client);t().diagnosed=true;log('完成异常诊断','核查计划数据、预算约束与原因假设；未认定确定性因果。');}finally{busy=false;render();}break;
      case'generate':if(busy||!t().infoComplete)break;busy=true;render();try{t().budgets=await S.generate(state.client);t().stage=2;t().maxStage=Math.max(2,t().maxStage);t().acknowledged=false;dirty=false;log('生成调整方案','A 减少 ¥100，B 增加 ¥100，日总预算保持 ¥1,000。');}finally{busy=false;render();window.scrollTo(0,0);}break;
      case'free-question':toast('当前仅支持上方快捷问题，其他问题已保留在输入框。');break;
      case'save-supplement':log('补充业务背景',t().supplement||'本次未添加额外业务背景。');toast('补充信息已保存到当前任务。');break;
      case'complete-data':t().infoComplete=true;log('补齐转化数据','数据回传状态更新为完整。');render();toast('转化数据已补齐。');break;
      case'back':gotoStep(Math.max(0,t().stage-1));break;
      case'restore-budgets':t().budgets=D.recommend(c());changed();render();toast('已恢复推荐预算。');break;
      case'save-draft':dirty=false;log('保存方案草稿',`预算 ${t().budgets.join(' / ')} 元，观察 ${t().days} 天。`);render();toast('草稿已保存，刷新后可继续。');break;
      case'preview':if(D.validate(c(),t(),r().memories).length){toast('请先修正校验问题。');break;}dirty=false;t().stage=3;t().maxStage=3;t().acknowledged=false;log('生成执行预览',`方案 V${t().version}，等待优化师确认。`);render();window.scrollTo(0,0);break;
      case'create-investigation':t().stage=3;t().maxStage=3;log('建立补查待办','负责人陈宁；下一工作日补查素材频次、受众差异与回传。没有投放写入。');render();break;
      case'execute':await execute();break;
      case'query-execution':await queryExecution();break;
      case'retry-confirm':closeModal();await execute(true);break;
      case'resolve-conflict':t().currentBudgets=[550,350,100];t().scenario='success';t().acknowledged=false;t().stage=2;t().maxStage=2;t().version++;log('配置冲突后重新核对','已加载平台最新配置 A 550 / B 350 / C 100，需重新预览并确认新版方案。');closeModal();render();toast('已载入最新配置，请核对预算后再次预览。');break;
      case'save-settings':t().scenario=document.getElementById('scenario').value;t().infoComplete=document.getElementById('data-mode').value==='complete';r().memories[0].status=document.getElementById('memory-mode').value==='valid'?'已确认':'已过期';t().acknowledged=false;log('更新运行场景',`执行场景 ${t().scenario}；数据${t().infoComplete?'完整':'不完整'}。`);closeModal();render();toast('运行设置已保存。');break;
      case'reset-confirm':if(busy){toast('请等待当前操作结束后再重置。');break;}openModal('重置全部业务数据？','<p>将清除本浏览器保存的十五个客户的任务、记忆修改和操作记录，恢复初始业务数据。</p>',btn('取消','close-modal')+btn('确认重置','reset','danger'));break;
      case'reset':S.reset();state=D.fresh();dirty=false;answer='';memoryFilter='全部';closeModal();save();render();toast('业务数据已恢复初始状态。');break;
      case'add-memory':openModal('新增客户记忆',`<p style="margin-bottom:18px">新增信息先进入待确认区，确认后才供当前客户参考。</p><div class="field"><label for="new-type">记忆类型</label><select id="new-type"><option>客户偏好</option><option>经营事实</option><option>待验证假设</option><option>历史经验</option></select></div><div class="field"><label for="new-text">记忆内容</label><textarea id="new-text" placeholder="写下具体要求或观察，并保留适用条件"></textarea></div><div class="field"><label for="new-source">来源说明或原文</label><textarea id="new-source" placeholder="例如客户沟通日期及原话"></textarea></div><div class="field"><label for="new-expiry">有效至</label><input id="new-expiry" type="date" value="2026-09-30"></div>`,btn('取消','close-modal')+btn('保存为待确认','save-new-memory','primary'));break;
      case'save-new-memory':{const text=document.getElementById('new-text').value.trim(),source=document.getElementById('new-source').value.trim(),expiry=document.getElementById('new-expiry').value;if(!text||!source||!expiry){toast('请填写内容、来源和有效期。');break;}r().memories.push({id:'manual-'+Date.now(),type:document.getElementById('new-type').value,text,source:'优化师手动录入 · 2026-09-09',original:source,expires:expiry,status:'待确认',version:1});log('新增待确认记忆',text);memoryFilter='全部';closeModal();render();toast('已保存为待确认记忆。');break;}
      case'handoff':openModal('客户交接摘要',`<div id="handoff-content"><h2>${c().name}</h2><p style="margin-top:12px">账户：${c().account}<br>目标 ROI：${fmt(c().target)}<br>日预算上限：¥${money(c().cap)}<br>负责优化师：陈宁</p><div class="divider"></div><h3>当前有效记忆</h3><ul class="guide-list">${r().memories.filter(m=>m.status==='已确认').map(m=>`<li>${esc(m.text)}</li>`).join('')}</ul><h3>未完成事项</h3><p style="margin-top:10px">${c().id==='qinghe'?taskStatus(t()):'日常观察，无异常调整任务'}<br>${r().memories.filter(m=>m.status==='待确认').length} 条客户记忆待核实。</p></div>`,btn('关闭','close-modal')+btn('复制摘要','copy-handoff','primary'),true);break;
      case'copy-handoff':try{await navigator.clipboard.writeText(document.getElementById('handoff-content').innerText);toast('交接摘要已复制。');}catch{const range=document.createRange();range.selectNodeContents(document.getElementById('handoff-content'));getSelection().removeAllRanges();getSelection().addRange(range);toast('内容已选中，请按 Ctrl+C 复制。');}break;
      case'export-logs':S.export({client:c().name,exportedAt:new Date().toISOString(),mock:true,logs:r().logs,execution:t().execution});toast('已导出当前客户的操作记录。');break;
      case'load-review':t().review.loaded=true;t().review.draft='适用条件：青禾家居，日总预算 ¥1,000，A 减少 ¥100、B 增加 ¥100 的阶段观察。\n观察结果：ROI 从 2.00 变为 2.40，仍低于目标 2.50。\n使用边界：无随机对照，不能证明预算调整带来全部变化；后续相似任务可参考此观察，仍需独立验证。';log('加载复盘数据','观察期数据已载入，结论保留因果限制。');render();break;
      case'confirm-review':{if(t().review.confirmed)break;const text=t().review.draft.trim();if(!text){toast('请填写经验内容后再确认。');break;}r().memories.push({id:'experience-'+Date.now(),type:'历史经验',text,status:'已确认',source:'预算调整复盘 · '+t().execution.id,original:'预置阶段观察数据：消耗 ¥3,000，成交 ¥7,200，ROI 2.40。缺少对照证据，仅描述变化。',expires:'2026-10-09',version:1});t().review.confirmed=true;log('确认复盘经验并写入记忆','仅写入当前客户；保留数据来源与因果限制。');render();toast('经验已写入当前客户记忆。');break;}
    }
  });
  function startQinghe(){if(busy){toast('当前操作进行中，请稍候。');return;}state.client='qinghe';go('task');}
  async function execute(retry=false){
    if(busy)return;
    if(!retry&&!t().acknowledged){toast('请先核对并确认具体调整内容。');return;}
    if(D.validate(c(),t(),r().memories).length){toast('当前方案未通过检查，请返回修改。');return;}
    if(t().execution&&(!retry||!['partial','failed'].includes(t().execution.status))){toast('已有执行记录，请先核对结果。');return;}
    if(t().scenario==='conflict'&&!retry){t().acknowledged=false;log('执行前检测到配置冲突','执行前检测：A 当前预算 550，B 当前预算 350，与预览不一致，未提交。');openModal('平台配置已发生变化',`<p>提交前的配置检查发现配置与预览不一致，已停止写入。</p><table class="conflict-table"><thead><tr><th>计划</th><th>原预览</th><th>检测到的值</th></tr></thead><tbody><tr><td>A</td><td>¥600</td><td>¥550</td></tr><tr><td>B</td><td>¥300</td><td>¥350</td></tr></tbody></table><p>“重新核对”将载入上方最新配置，并生成新方案版本。修改前后差异会重新计算，之后必须重新确认。</p>`,btn('取消','close-modal')+btn('重新核对','resolve-conflict','primary'));render();return;}
    const clientId=state.client,record=state.records[clientId],client=c();
    const ex=D.createExecution(client,record.task,retry?record.task.execution:null);if(retry)ex.scenario='success';
    record.task.execution=ex;record.task.stage=4;record.task.maxStage=4;record.task.acknowledged=false;busy=true;
    log(retry?'确认重试未完成动作':'确认并提交投放执行',`批准版本 V${ex.version}，请求标识 ${ex.id}。`,clientId);render();window.scrollTo(0,0);
    try{record.task.execution=await S.execute(ex);if(record.task.execution.status==='success')record.task.review=record.task.review||{loaded:false,confirmed:false};log('投放执行结果',`${ex.id} · ${record.task.execution.status}，分项结果已记录。`,clientId);}catch{record.task.execution=D.settleExecution(ex,'unknown');log('执行结果未确认','请查询本次请求状态，避免重复提交。',clientId);}finally{busy=false;save();render();}
  }
  async function queryExecution(){if(busy)return;const clientId=state.client,record=state.records[clientId];busy=true;render();try{record.task.execution=await S.query(record.task.execution);log('查询执行状态',`当前状态：${record.task.execution.status}。`,clientId);if(record.task.execution.status==='success'){record.task.review=record.task.review||{loaded:false,confirmed:false};toast('已确认全部目标动作成功。');}else{const ex=record.task.execution;openModal('核对配置并重新确认',`<p>已查询当前配置。只提交未成功的目标动作，已成功项保持不变。</p><div style="margin:15px -20px">${budgetSummary(ex)}</div><div class="validation">重试将绑定方案 V${record.task.version}，本次重新执行未完成动作。</div>`,btn('暂不重试','close-modal')+btn('确认并重试','retry-confirm','primary'));}}finally{busy=false;save();render();}}
  overlay.addEventListener('click',e=>{if(e.target.classList.contains('overlay-backdrop'))closeModal();});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='assistant-input'){e.preventDefault();smartAnswer(e.target.value);return;}if(!overlay.firstChild)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=[...overlay.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  save();render();
})();
